+		$path = $path ?: '/';
+
+		$cookies = $response->cookies();
+		foreach ($cookies as $name => $cookie) {
+			if (empty($cookie['domain'])) {
+				$cookie['domain'] = $host;
+			}
+			if (empty($cookie['path'])) {
