+	public function set(array $properties = [], $useSetters = true) {
+		if (!$useSetters) {
+			$this->_properties = $properties + $this->_properties;
+			return $this;
+		}
+
+		foreach($properties as $property => $value) {
+			if (method_exists($this, 'set' . ucFirst($property))) {
