 		if ( !s.hasContent ) {

 			// If data is available, append data to url
-			if ( s.data ) {
+			// Only append once, do not re-append if data is already in url
+			var dataAppendedToUrl = ( new RegExp( "(&|\\?)" + s.data + "(&|$)" ) ).test( s.url );

