+		if ((error = git_diff_tree_to_tree(&diff, blame->repository, parenttree, committree, &diffopts)) < 0)
+			goto cleanup;
+
+		/* Generate a full diff between the two trees */
+		if (git_diff_num_deltas(diff) > 0) {
+			diffopts.pathspec.count = 0;
+			if ((error = git_diff_tree_to_tree(&diff, blame->repository, parenttree, committree, &diffopts)) < 0)

