+   /* "@{-N}" form means walk back N checkouts. That means the HEAD log. */
+   if (refspeclen == 0 && !git__prefixcmp(reflogspec, "@{-")) {
+      regex_t regex;
+      int regex_error;
+
+      if (git__strtol32(&n, reflogspec+3, NULL, 0) < 0 ||
