+//Takes .pfx or .p12 and password in string or buffer format 
+Handle<Value> SecureContext::LoadPKCS12(const Arguments& args) {
+  HandleScope scope;
+
+  PKCS12 * p12 = NULL;
+  EVP_PKEY * pkey = NULL;
+  X509 * cert = NULL;
+  STACK_OF(X509) * ca = NULL;
+  BIO * bio_in = NULL;
+
+  bool ret = true;
+  char *pass = "";
+  bool passAllocated = false;
+
+  SecureContext *sc = ObjectWrap::Unwrap<SecureContext>(args.Holder());
+
+  if (args.Length() < 1) {
+      return ThrowException(Exception::TypeError(
+                  String::New("Bad parameter")));
+  }
+
+  if (args.Length() >= 2) {
+    ASSERT_IS_STRING_OR_BUFFER(args[1]);
+
+    int passlen = DecodeBytes(args[1], BINARY);
+
+    if (passlen < 0) {
+      return ThrowException(Exception::TypeError(
+                          String::New("Bad password")));
+    }
+    pass = new char[passlen];
+    passAllocated = true;
+    int pass_written = DecodeWrite(pass, passlen, args[1], BINARY);
+
+    assert(pass_written == passlen);
+  }
+
+  bio_in = LoadBIO(args[0]);
+  if (bio_in == NULL) {
+    ret = false;
+    goto cleanup;
+  }
+    
+  if (d2i_PKCS12_bio(bio_in, &p12)) {
+
+    if (PKCS12_parse(p12, pass, &pkey, &cert, &ca)) {
+
+      BIO *bio_out = BIO_new(BIO_s_mem());
+      if (bio_out == NULL) {
+        ret = false;
+        goto cleanup;
+      }
+
+      if (PEM_write_bio_X509(bio_out, cert)) {
+
+        if (!SSL_CTX_use_certificate_chain(sc->ctx_, bio_out)) {
+            ret = false;
+            BIO_free(bio_out);
+            goto cleanup;
+        }
+      }
+      BIO_free(bio_out);
+
+      bio_out = BIO_new(BIO_s_mem());
+      if (bio_out == NULL) {
+        ret = false;
+        goto cleanup;
+      }
+            
+      if (PEM_write_bio_PrivateKey(bio_out, pkey, NULL, NULL, 0, 0, NULL)) {
+        SSL_CTX_use_PrivateKey(sc->ctx_, pkey);
+        EVP_PKEY_free(pkey);
+      }
+      BIO_free(bio_out);
+
+      bool newCAStore = false;
+
+      if (sc->ca_store_ == NULL) {
+          sc->ca_store_ = X509_STORE_new();
+          newCAStore = true;
+      }
+
+      while (true) {
+        X509* aCA = sk_X509_pop(ca);
+        if (!aCA) break;
+                
+        X509_STORE_add_cert(sc->ca_store_, aCA);
+        SSL_CTX_add_client_CA(sc->ctx_, aCA);
+
+        X509_free(aCA);
+      }
+
+      if (ca) {
+          sk_X509_free(ca);
+      } 
+
+      if (newCAStore) {
+          SSL_CTX_set_cert_store(sc->ctx_, sc->ca_store_);
+      }
+
+      PKCS12_free(p12);
+    }
+  }
+
+  cleanup:
+
+  if (bio_in) {
+    BIO_free(bio_in);
+  }
+    
+  if (pkey) {
+    EVP_PKEY_free(pkey);
+  }

